from z3 import *

n = 11
edges = {}
for i in range(n):
    for j in range(i+1, n):
        edges[(i, j)] = Bool(f"e_{i}_{j}")

def edge(i, j):
    if i > j:
        i, j = j, i
    return edges[(i, j)]

s = Solver()

# Known edges
s.add(edge(3, 7) == True)
s.add(edge(2, 9) == True)
s.add(edge(0, 9) == True)

# Degrees
for i in range(n):
    deg = Sum([If(edge(i, j), 1, 0) for j in range(n) if i != j])
    s.add(deg >= 3)
    s.add(deg <= 5)

# Number of edges
total_edges = Sum([If(e, 1, 0) for e in edges.values()])
s.add(total_edges >= 17)
s.add(total_edges <= 19)

# Chromatic number <= 4
colors = [Int(f"c_{i}") for i in range(n)]
for i in range(n):
    s.add(colors[i] >= 0, colors[i] <= 3)

for i in range(n):
    for j in range(i+1, n):
        s.add(Implies(edge(i, j), colors[i] != colors[j]))

# Chromatic number >= 3 (contains a triangle)
triangle = Or([And(edge(i, j), edge(j, k), edge(i, k)) for i in range(n) for j in range(i+1, n) for k in range(j+1, n)])
s.add(triangle)

if s.check() == sat:
    m = s.model()
    res = []
    for i in range(n):
        for j in range(i+1, n):
            if is_true(m[edge(i, j)]):
                res.append((i, j))
    print(res)
else:
    print("UNSAT")

from pysat.solvers import Glucose3
from pysat.card import CardEnc, EncType
from pysat.formula import IDPool

n = 11
min_deg = 3
max_deg = 5
min_edges = 17
max_edges = 19

vpool = IDPool()

def edge_var(u, v):
    if u > v:
        u, v = v, u
    return vpool.id(f"e_{u}_{v}")

solver = Glucose3()

# Known edges
solver.add_clause([edge_var(3, 7)])
solver.add_clause([edge_var(2, 9)])
solver.add_clause([edge_var(0, 9)])

# Degrees
for i in range(n):
    incident_edges = [edge_var(i, j) for j in range(n) if i != j]
    cnf1 = CardEnc.atleast(lits=incident_edges, bound=min_deg, encoding=EncType.seqcounter, vpool=vpool)
    for clause in cnf1.clauses:
        solver.add_clause(clause)
    cnf2 = CardEnc.atmost(lits=incident_edges, bound=max_deg, encoding=EncType.seqcounter, vpool=vpool)
    for clause in cnf2.clauses:
        solver.add_clause(clause)

# Total edges
all_edges = [edge_var(i, j) for i in range(n) for j in range(i+1, n)]
cnf3 = CardEnc.atleast(lits=all_edges, bound=min_edges, encoding=EncType.seqcounter, vpool=vpool)
for clause in cnf3.clauses:
    solver.add_clause(clause)
cnf4 = CardEnc.atmost(lits=all_edges, bound=max_edges, encoding=EncType.seqcounter, vpool=vpool)
for clause in cnf4.clauses:
    solver.add_clause(clause)

# Chromatic number <= 4
def color_var(i, k):
    return vpool.id(f"c_{i}_{k}")

for i in range(n):
    solver.add_clause([color_var(i, k) for k in range(4)])
    for k1 in range(4):
        for k2 in range(k1+1, 4):
            solver.add_clause([-color_var(i, k1), -color_var(i, k2)])

for i in range(n):
    for j in range(i+1, n):
        for k in range(4):
            solver.add_clause([-edge_var(i, j), -color_var(i, k), -color_var(j, k)])

# Chromatic number >= 3
# We can enforce this by saying it's not 2-colorable.
# Let's just find a graph, and if it's 2-colorable, we block it.
# Actually, enforcing a triangle is sufficient but not necessary (e.g., odd cycle of length 5).
# Let's just enforce that it's not 2-colorable.
# To do this, we can add a boolean variable for each edge, and check if it's bipartite.
# Wait, we can just solve, and if the graph is bipartite, we add a blocking clause and solve again.

while True:
    if solver.solve():
        model = solver.get_model()
        edges = []
        for i in range(n):
            for j in range(i+1, n):
                if model[vpool.id(f"e_{i}_{j}") - 1] > 0:
                    edges.append((i, j))

        # Check if bipartite
        from collections import defaultdict
        adj = defaultdict(list)
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        color = {}
        is_bipartite = True
        for i in range(n):
            if i not in color:
                q = [i]
                color[i] = 0
                while q:
                    u = q.pop(0)
                    for v in adj[u]:
                        if v not in color:
                            color[v] = 1 - color[u]
                            q.append(v)
                        elif color[v] == color[u]:
                            is_bipartite = False
                            break
                    if not is_bipartite:
                        break
            if not is_bipartite:
                break

        if not is_bipartite:
            print(edges)
            break
        else:
            # Block this graph
            blocking_clause = []
            for i in range(n):
                for j in range(i+1, n):
                    if (i, j) in edges:
                        blocking_clause.append(-edge_var(i, j))
                    else:
                        blocking_clause.append(edge_var(i, j))
            solver.add_clause(blocking_clause)
    else:
        print("UNSAT")
        break
